import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Calculate correlations and identify near-duplicates
    corr_matrix = np.corrcoef(feats.x.T)
    near_dupes = set()
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            if abs(corr_matrix[i,j]) >= 0.6:
                near_dupes.add((feats.ids[i], feats.ids[j]))

    # Filter out near-duplicates, keeping first occurrence
    unique_ids = []
    seen = set()
    for fid in feats.ids:
        if any(fid in pair for pair in near_dupes):
            # Check if this feature's pair is already processed
            found = False
            for pair in near_dupes:
                if fid in pair and pair[0] in seen or pair[1] in seen:
                    found = True
                    break
            if not found:
                unique_ids.append(fid)
                seen.add(fid)
        else:
            unique_ids.append(fid)
            seen.add(fid)

    # Calculate effect sizes using Welch's t-test
    effect_sizes = []
    for i, fid in enumerate(unique_ids):
        x_col = feats.x[:, feats.column(fid)]
        y = feats.y
        group0 = x_col[y == 0]
        group1 = x_col[y == 1]
        if len(group0) > 0 and len(group1) > 0:
            t_stat, _ = stats.ttest_ind(group0, group1, equal_var=False)
            effect_sizes.append((fid, abs(t_stat)))
        else:
            effect_sizes.append((fid, 0))

    # Sort by effect size
    effect_sizes.sort(key=lambda x: x[1], reverse=True)

    # Select top features (limit to 3 to keep model small)
    top_features = [fid for fid, _ in effect_sizes[:3]]

    # Check for strong correlations between top features
    selected_corr_pairs = []
    for i in range(len(top_features)):
        for j in range(i+1, len(top_features)):
            fid1, fid2 = top_features[i], top_features[j]
            if any((fid1, fid2) in pair or (fid2, fid1) in pair for pair in near_dupes):
                selected_corr_pairs.append((fid1, fid2))

    # Build design
    drivers = tuple(top_features)
    columns = tuple(unique_ids)
    products = tuple(selected_corr_pairs)
    loadings = {fid: 1.0 for fid in unique_ids}

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)
